def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.167.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.166.0"' not in init:
        sys.exit("ABORT: not at v3.166.0.")
    for k in ("master_governance", "backups_continuity"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("SYS3", LESSONS_S3, QUESTIONS_S3, 9) + _validate("SYS4", LESSONS_S4, QUESTIONS_S4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("SYS 3", LESSONS_S3, QUESTIONS_S3, "master_governance",
         "Master data governance in ZhiftERP: the four properties of a governed register and master-error leverage; naming decided per register (Customer/Supplier Naming By, Item Code schemes) and the Naming Series tool with its lawful counter uses; duplicate detection and the Rename > Merge with existing procedure; creation governance with the request lane and walk-in rule; field completeness (Item Group, Item Defaults, Territory, Tax Withholding Category) enforced by mandatory fields and saved-filter reads; and the six-step governed Data Import with Insert versus Update discipline."),
        ("SYS 4", LESSONS_S4, QUESTIONS_S4, "backups_continuity",
         "Backups and continuity on the managed platform: the two custodies; the database-plus-files completeness rule; RPO and RTO held in writing; the Download Backups page with the daily presence check and the monthly off-platform copy; the three restore paths with sets named by timestamp; the monthly restore drill and the annual full dress; the before-change backup with the no-timestamp-no-run reflex; and the four-scenario continuity runbook with degraded tills and governed re-entry."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.166.0"', '"3.167.0"'))
    print("  data: SYSADMIN 3 + 4 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.167.0")


if __name__ == "__main__":
    main()
